const chatInput = String($json.chatInput ?? '').trim();
const codeLabel = /^\s*c[óo]digo\s*[:=\-]?\s*/i;
const codeShape = /^[\d\s.\-\/]+$/;
const withoutLabel = chatInput.replace(codeLabel, '').trim();
const codigoDigits = withoutLabel.replace(/\D/g, '');
// One digit is enough: a partial função code is a legitimate search.
const isCodeInput = codigoDigits.length >= 1 && codeShape.test(withoutLabel);

return [{
  json: {
    chat_input: chatInput,
    is_code_input: isCodeInput,
    codigo_digits: codigoDigits,
  },
}];

const digits = String($json.codigo_digits ?? '').trim();
const maxRows = Number($json.max_rows);

if (!digits || !/^\d+$/.test(digits)) {
  throw new Error('Código sem dígitos para a busca por código.');
}
if (!Number.isInteger(maxRows) || maxRows < 1) {
  throw new Error('Search configuration is invalid: max_rows must be a positive integer.');
}

// Leading zeros never matter: production stores them, users drop them. A code
// made only of zeros must not turn the LIKE into a match-everything pattern.
const needle = digits.replace(/^0+/, '') || '0';

return [{ json: { codigo_needle: needle, termo_codigo: digits, max_rows: maxRows } }];

// Build the extraction request body here so the HTTP node's expression stays a
// single JSON.stringify() without nested brace literals.
const chatInput = String($json.chat_input ?? '').trim();
const SYSTEM_PROMPT = `Você extrai o termo de busca de mensagens sobre funções e subfunções orçamentárias.

Responda somente com JSON no formato {"intencao": "saudacao|ajuda|busca", "termo": "..."}.

Intenções:
- "saudacao": cumprimentos e cortesias ("oi", "bom dia", "obrigado").
- "ajuda": perguntas sobre como usar o assistente ou o que é função e subfunção.
- "busca": todo o resto, inclusive palavras isoladas, termos desconhecidos e códigos.

Regras do termo: minúsculas, singular, preserve os acentos; remova verbos, artigos e
pedidos ("quero", "preciso", "de", "para"); se a mensagem for um código, copie só os
dígitos. Para "saudacao" e "ajuda", deixe o termo vazio.

Exemplos:
- "oi" -> {"intencao": "saudacao", "termo": ""}
- "como buscar?" -> {"intencao": "ajuda", "termo": ""}
- "policiamento ostensivo" -> {"intencao": "busca", "termo": "policiamento"}
- "quero ver saúde" -> {"intencao": "busca", "termo": "saúde"}
- "061" -> {"intencao": "busca", "termo": "061"}`;

return [{
  json: {
    chat_input: chatInput,
    request_body: {
      model: 'qwen3:4b',
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: chatInput },
      ],
      stream: false,
      think: false,
      format: {
        type: 'object',
        properties: {
          intencao: { type: 'string', enum: ['saudacao', 'ajuda', 'busca'] },
          termo: { type: 'string' },
        },
        required: ['intencao', 'termo'],
        additionalProperties: false,
      },
      options: { temperature: 0, num_ctx: 4096 },
      keep_alive: '30m',
    },
  },
}];

// Turn the extraction reply into an intenção and a single termo. Anything the
// model does not route as greeting/help is a search, and a malformed or missing
// reply falls back to the raw message, so the workflow still answers.
const userText = String($('Build Chat Request').first().json.chat_input ?? '').trim();
const content = $json?.message?.content ?? $json?.output ?? '';
const raw = typeof content === 'string' ? content : JSON.stringify(content ?? '');

let parsed = null;
const first = raw.indexOf('{');
const last = raw.lastIndexOf('}');
if (first !== -1 && last > first) {
  try {
    parsed = JSON.parse(raw.slice(first, last + 1));
  } catch (error) {
    // fall through to the plain-text branch
  }
}

let term = parsed ? String(parsed?.termo ?? '') : '';
if (!parsed) {
  term = raw.split(/\r?\n/).map((line) => line.trim()).filter(Boolean)[0] || '';
}
term = term.replace(/^termo\s*[:=]\s*/i, '');
term = term.replace(/^["'`\u201c\u201d]+|["'`\u201c\u201d]+$/g, '');
// Accents stay: the floor in 3.4 was measured on accented query text.
term = term.replace(/\s+/g, ' ').trim().toLowerCase();
if (!term) {
  term = userText;
}

const normalized = String(parsed?.intencao ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const intencao = normalized === 'saudacao' || normalized === 'ajuda' ? normalized : 'busca';
const isGreeting = intencao !== 'busca';

return [{
  json: {
    intencao,
    is_greeting: isGreeting,
    termo: isGreeting ? '' : term,
    chat_input: userText,
  },
}];

// Greeting and help both get the fixed text: the live prompt repeats its
// opening question for a dúvida and never calls a tool for one.
const ORIENTATION = 'Qual a Subfunção? Digite o código, nome ou palavra-chave para localizar:\nExemplos: 061, 121, Administração Geral, Policiamento...\nAparecerão todas as subfunções que contenham o termo buscado.';

return [{ json: { output: ORIENTATION, text: ORIENTATION } }];

// Join the extracted term with the tunable search configuration. The term is
// the only value the lexical SQL needs for scoring and for the reply.
const config = $('Search Config (floor, max_rows)').first().json;
const termo = String($('Parse Termo').first().json?.termo ?? '').trim();

const floor = Number(config.similarity_floor);
const maxRows = Number(config.max_rows);
if (!Number.isFinite(floor) || !Number.isInteger(maxRows) || maxRows < 1) {
  throw new Error('Search configuration is invalid: similarity_floor must be a number and max_rows a positive integer.');
}

return [{ json: { termo, similarity_floor: floor, max_rows: maxRows } }];

// Render the reply deterministically: result rows never reach a model.
const HEADER = '| Cód. Subfunção | Descrição Subfunção | Cód. Função | Descrição Função |';
const DIVIDER = '|---|---|---|---|';
const CLOSING = 'Deseja pesquisar outra Subfunção?';

const items = $input.all().map((item) => item.json ?? {});
// A search that matches nothing still returns one sentinel row, so the term and
// the untruncated total always travel with the rows.
const rows = items.filter((row) => String(row?.codigosubfuncao ?? '').trim() !== '');
const first = items[0] ?? {};

const termo = String(first.termo ?? '').trim();
const reported = Number(first.total);
const total = Number.isFinite(reported) ? reported : rows.length;

const cell = (value) => String(value ?? '')
  .replace(/[\r\n]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .replace(/\|/g, '\\|');

if (rows.length === 0) {
  const reply = `Não encontrei nenhuma Subfunção para *${termo}*. Tente outro termo.\n\n${CLOSING}`;
  return [{ json: { output: reply, text: reply } }];
}

const notice = rows.length < total ? `Mostrando ${rows.length} de ${total} resultados.` : '';
const table = [
  HEADER,
  DIVIDER,
  ...rows.map((row) => `| ${cell(row.codigosubfuncao)} | ${cell(row.descricaosubfuncao)} | ${cell(row.codigofuncao)} | ${cell(row.descricaofuncao)} |`),
].join('\n');

const reply = [
  `Encontrei as seguintes Subfunções para *${termo}*:`,
  notice,
  table,
  CLOSING,
].filter(Boolean).join('\n\n');

return [{ json: { output: reply, text: reply } }];
